SELECT 
FROM cus_order_template
WHERE is_deleted = 0
  AND status_enum = #{statusEnum}
  AND scene_enum = #{sceneEnum}
  AND template_kind_enum = #{templateKindEnum}
  AND (
    binding_enum = 'GLOBAL'

        OR (binding_enum = 'DEPT' AND object_id = #{deptId})
        OR (binding_enum = 'PERSONAL' AND object_id = #{practitionerId})

  )
ORDER BY sort_weight ASC, name ASC

SELECT 
FROM cus_order_template
WHERE is_deleted = 0
  AND template_kind_enum = #{templateKindEnum}

  AND name LIKE CONCAT('%', #{keyword}, '%')


  AND binding_enum = #{bindingEnum}


  AND scene_enum = #{sceneEnum}


  AND status_enum = #{statusEnum}

ORDER BY sort_weight ASC, updated_at DESC
